import ast,hashlib,json
from pathlib import Path
from verify_mixed_live import render
root=Path('.')
manifest=json.loads(Path('rag/eval/baselines/routing_v2_frozen/manifest.json').read_text())
for filename in ('rag/service/intent_classifier.py','rag/service/store_contract.py','rag/service/semantic_router.py','rag/service/routing_prototypes.json','rag/service/answer_service.py','rag/retrieval/search_chunks.py'):
    assert hashlib.sha256(Path(filename).read_bytes()).hexdigest()==manifest['files'][filename],filename
old=ast.parse(Path('deploy/backups/mixed-2026-10-12/ticket_service.py').read_text());new=ast.parse(Path('rag/service/ticket_service.py').read_text())
def rule(tree):return ast.dump(next(n for n in tree.body if isinstance(n,ast.FunctionDef) and n.name=='is_ticket_question'))
def literal(tree,name):return ast.literal_eval(next(n.value for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id==name for t in n.targets)))
assert rule(old)==rule(new)
for name in ('CATALOG_SQL','TICKET_SQL'):assert literal(old,name)==literal(new,name)
for filename in ('mixed_v1_live_run1','mixed_v1_live_fault_scope_followup'):
    path=Path('rag/eval/reports')/(filename+'.json');report=json.loads(path.read_text());assert report['run_complete']
    path.with_suffix('.md').write_text(render(report))
print('Verified unchanged classifier, rules, thresholds, prompt, SQL literals and search source')
PY
